import React, { useState, useEffect } from 'react';
import classes from './Modal.module.scss';

const ModalUnsubscribed = ({ onClose }) => {
  const [isVisible, setIsVisible] = useState(true);
  const [isClosing, setIsClosing] = useState(false);
  const [timerWidth, setTimerWidth] = useState(100); // Начальная ширина таймера

  useEffect(() => {
    const timer = setTimeout(() => {
      setIsClosing(true);
    }, 3000);

    const interval = setInterval(() => {
      setTimerWidth((prevWidth) => Math.max(0, prevWidth - (100 / 30))); // Обновляем ширину таймера каждую 100мс
    }, 100);

    return () => {
      clearTimeout(timer);
      clearInterval(interval);
    };
  }, []);

  const handleAnimationEnd = () => {
    if (isClosing) {
      onClose();
    }
  };

  return (
    isVisible ? (
      <div
        className={`${classes.modal} ${classes.modalBottomRight} ${isClosing ? classes.modalFadeOut : ''}`}
        onAnimationEnd={handleAnimationEnd}
      >
        <h2 className={classes.modalTitle}>Вы отписались от услуги</h2>
        <div className={classes.timerLine} style={{ width: `${timerWidth}%` }} />
      </div>
    ) : null
  );
};

export default ModalUnsubscribed;
